import type { Entry, FileEntry, FileType, FolderEntry } from './data'

/** The folders from the root down to `id`, or null if it no longer exists */
export function findPath(
  folder: FolderEntry,
  id: string,
): FolderEntry[] | null {
  if (folder.id === id) return [folder]
  for (const child of folder.children) {
    if (child.kind !== 'folder') continue
    const path = findPath(child, id)
    if (path) return [folder, ...path]
  }
  return null
}

/** The entry inside `ancestorId` that leads down to `descendantId` */
export const childToward = (ancestorId: string, descendantId: string) =>
  `${ancestorId}/${descendantId.slice(ancestorId.length + 1).split('/')[0]}`

/** A file's size, or everything inside a folder */
export const sizeOf = (entry: Entry): number =>
  entry.kind === 'file'
    ? entry.size
    : entry.children.reduce((sum, c) => sum + sizeOf(c), 0)

export type SortKey = 'name' | 'size' | 'modified'
export interface Sort {
  id: SortKey
  desc: boolean
}

/** Folders always come first, whichever way the column is sorted */
export function sortEntries(entries: Entry[], sort: Sort): Entry[] {
  const dir = sort.desc ? -1 : 1
  const by: Record<SortKey, (a: Entry, b: Entry) => number> = {
    name: (a, b) =>
      a.name.localeCompare(b.name, 'en', {
        numeric: true,
        sensitivity: 'base',
      }),
    size: (a, b) => sizeOf(a) - sizeOf(b),
    modified: (a, b) => a.modified.localeCompare(b.modified),
  }
  return [...entries].sort((a, b) => {
    if (a.kind !== b.kind) return a.kind === 'folder' ? -1 : 1
    return by[sort.id](a, b) * dir || by.name(a, b)
  })
}

/** The tree without the given entries, wherever they are */
export function removeIds(folder: FolderEntry, ids: Set<string>): FolderEntry {
  return {
    ...folder,
    children: folder.children
      .filter((c) => !ids.has(c.id))
      .map((c) => (c.kind === 'folder' ? removeIds(c, ids) : c)),
  }
}

export function formatSize(bytes: number) {
  if (bytes < 1024) return `${bytes} B`
  const units = ['KB', 'MB', 'GB']
  let n = bytes / 1024
  let i = 0
  while (n >= 1024 && i < units.length - 1) {
    n /= 1024
    i++
  }
  return `${n >= 10 ? Math.round(n) : n.toFixed(1).replace(/\.0$/, '')} ${units[i]}`
}

const monthNames = [
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
]

/** "2026-11-12" → "Nov 12, 2026", without Date, so time zones can't shift it */
export function formatDate(iso: string) {
  const [y, m, d] = iso.split('-').map(Number)
  return `${monthNames[m - 1]} ${d}, ${y}`
}

export const typeLabels: Record<FileType, string> = {
  pdf: 'PDF document',
  image: 'Image',
  doc: 'Word document',
  sheet: 'Spreadsheet',
  video: 'Video',
  archive: 'ZIP archive',
  design: 'Figma file',
  text: 'Markdown',
}

export const kindLabel = (entry: Entry) =>
  entry.kind === 'folder' ? 'Folder' : typeLabels[entry.type]

export const itemCount = (folder: FolderEntry) => {
  const n = folder.children.length
  return n === 0 ? 'Empty' : `${n} ${n === 1 ? 'item' : 'items'}`
}

/** The facts for a file's expanded row, type-specific ones first */
export function details(file: FileEntry, path: FolderEntry[]) {
  const rows: { label: string; value: string }[] = []
  if (file.dimensions)
    rows.push({ label: 'Dimensions', value: file.dimensions })
  if (file.pages) rows.push({ label: 'Pages', value: String(file.pages) })
  if (file.duration) rows.push({ label: 'Duration', value: file.duration })
  if (file.sheets) rows.push({ label: 'Sheets', value: String(file.sheets) })
  rows.push(
    { label: 'Type', value: typeLabels[file.type] },
    {
      label: 'Size',
      value: `${formatSize(file.size)} (${file.size.toLocaleString('en-US')} bytes)`,
    },
    { label: 'Created', value: formatDate(file.created) },
    { label: 'Modified', value: formatDate(file.modified) },
    { label: 'Owner', value: file.owner },
    { label: 'Version', value: `v${file.version}` },
    { label: 'Location', value: path.map((f) => f.name).join(' / ') },
  )
  return rows
}

import {
  File,
  FileArchive,
  FileImage,
  FileSpreadsheet,
  FileText,
  FileVideo,
  Folder,
  PenTool,
} from 'lucide-react'
import type { LucideIcon } from 'lucide-react'

import { cn } from '#/lib/utils'
import type { Entry, FileType } from './data'

const icons: Record<FileType, { icon: LucideIcon; color: string }> = {
  pdf: { icon: FileText, color: 'text-red-600 dark:text-red-400' },
  image: { icon: FileImage, color: 'text-violet-600 dark:text-violet-400' },
  doc: { icon: FileText, color: 'text-blue-600 dark:text-blue-400' },
  sheet: {
    icon: FileSpreadsheet,
    color: 'text-emerald-600 dark:text-emerald-400',
  },
  video: { icon: FileVideo, color: 'text-amber-600 dark:text-amber-400' },
  archive: { icon: FileArchive, color: 'text-muted-foreground' },
  design: { icon: PenTool, color: 'text-pink-600 dark:text-pink-400' },
  text: { icon: File, color: 'text-muted-foreground' },
}

/** The icon is decoration: the Type column says the same in words */
export function FileIcon({
  entry,
  className,
}: {
  entry: Entry
  className?: string
}) {
  const { icon: Icon, color } =
    entry.kind === 'folder'
      ? { icon: Folder, color: 'text-sky-600 dark:text-sky-400' }
      : icons[entry.type]
  return (
    <Icon
      aria-hidden
      className={cn(
        'size-4 shrink-0',
        color,
        entry.kind === 'folder' && 'fill-current/15',
        className,
      )}
    />
  )
}

import type { FileEntry, FolderEntry } from './data'
import { FileIcon } from './file-icon'
import { details } from './files'

/** The expanded row: everything known about one file */
export function FileDetails({
  file,
  path,
}: {
  file: FileEntry
  path: FolderEntry[]
}) {
  return (
    <div className="flex flex-col gap-4 py-2 pl-1 sm:flex-row">
      <div
        aria-hidden
        className="flex size-20 shrink-0 items-center justify-center rounded-md border bg-muted/50"
      >
        <FileIcon entry={file} className="size-8" />
      </div>
      <div className="min-w-0 flex-1 space-y-3">
        <dl className="grid grid-cols-[auto_1fr] gap-x-6 gap-y-1.5 text-sm sm:grid-cols-[auto_1fr_auto_1fr]">
          {details(file, path).map((row) => (
            <div key={row.label} className="contents">
              <dt className="text-muted-foreground">{row.label}</dt>
              <dd className="min-w-0 break-words">{row.value}</dd>
            </div>
          ))}
        </dl>
        {file.tags.length ? (
          <ul aria-label="Tags" className="flex flex-wrap gap-1.5">
            {file.tags.map((tag) => (
              <li
                key={tag}
                className="rounded-full border px-2 py-0.5 text-xs text-muted-foreground"
              >
                {tag}
              </li>
            ))}
          </ul>
        ) : null}
      </div>
    </div>
  )
}

import { ArrowDown, ArrowUp, ChevronRight } from 'lucide-react'
import type { Column, ColumnDef, Table } from '@tanstack/react-table'

import { Checkbox } from '#/components/ui/checkbox'
import { cn } from '#/lib/utils'
import type { Entry } from './data'
import { FileIcon } from './file-icon'
import { formatDate, formatSize, itemCount, kindLabel, sizeOf } from './files'

export interface BrowserMeta {
  open: (folderId: string) => void
}

const getMeta = (table: Table<Entry>) =>
  table.options.meta as unknown as BrowserMeta

function SortHeader({
  column,
  label,
  align = 'left',
}: {
  column: Column<Entry>
  label: string
  align?: 'left' | 'right'
}) {
  const sorted = column.getIsSorted()
  const Icon = sorted === 'desc' ? ArrowDown : ArrowUp
  return (
    <button
      type="button"
      onClick={column.getToggleSortingHandler()}
      className={cn(
        'group/sort inline-flex items-center gap-1 rounded-sm outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50',
        align === 'right' && 'ml-auto flex-row-reverse',
      )}
    >
      {label}
      <Icon
        aria-hidden
        className={cn(
          'size-3.5',
          !sorted && 'opacity-0 group-hover/sort:opacity-40',
        )}
      />
    </button>
  )
}

export const columns: ColumnDef<Entry>[] = [
  {
    id: 'select',
    header: ({ table }) => (
      <Checkbox
        aria-label="Select everything in this folder"
        disabled={!table.getRowCount()}
        checked={
          table.getIsAllRowsSelected()
            ? true
            : table.getIsSomeRowsSelected()
              ? 'indeterminate'
              : false
        }
        onCheckedChange={(on) => table.toggleAllRowsSelected(!!on)}
      />
    ),
    cell: ({ row }) => (
      <Checkbox
        aria-label={`Select ${row.original.name}`}
        checked={row.getIsSelected()}
        onCheckedChange={(on) => row.toggleSelected(!!on)}
      />
    ),
  },
  {
    id: 'name',
    accessorFn: (entry) => entry.name,
    header: ({ column }) => <SortHeader column={column} label="Name" />,
    cell: ({ row, table }) => {
      const entry = row.original
      const button =
        'flex min-w-0 items-center gap-2 rounded-sm text-left outline-none hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/50'
      // A folder's name opens it; a file's name shows its details
      return entry.kind === 'folder' ? (
        <button
          type="button"
          data-entry={entry.id}
          onClick={() => getMeta(table).open(entry.id)}
          className={cn(button, 'font-medium')}
        >
          <FileIcon entry={entry} />
          <span className="truncate">{entry.name}</span>
        </button>
      ) : (
        <button
          type="button"
          data-entry={entry.id}
          aria-expanded={row.getIsExpanded()}
          onClick={row.getToggleExpandedHandler()}
          className={button}
        >
          <FileIcon entry={entry} />
          <span className="truncate">{entry.name}</span>
          <ChevronRight
            aria-hidden
            className={cn(
              'size-3.5 shrink-0 text-muted-foreground transition-transform motion-reduce:transition-none',
              row.getIsExpanded() && 'rotate-90',
            )}
          />
          <span className="sr-only">
            , {row.getIsExpanded() ? 'hide' : 'show'} details
          </span>
        </button>
      )
    },
  },
  {
    id: 'kind',
    header: 'Type',
    cell: ({ row }) => (
      <span className="text-muted-foreground">{kindLabel(row.original)}</span>
    ),
  },
  {
    id: 'size',
    accessorFn: (entry) => sizeOf(entry),
    header: ({ column }) => (
      <div className="flex">
        <SortHeader column={column} label="Size" align="right" />
      </div>
    ),
    cell: ({ row }) => (
      <span className="block text-right text-muted-foreground tabular-nums">
        {row.original.kind === 'folder'
          ? itemCount(row.original)
          : formatSize(row.original.size)}
      </span>
    ),
  },
  {
    id: 'modified',
    accessorFn: (entry) => entry.modified,
    header: ({ column }) => <SortHeader column={column} label="Modified" />,
    cell: ({ row }) => (
      <span className="whitespace-nowrap text-muted-foreground tabular-nums">
        {formatDate(row.original.modified)}
      </span>
    ),
  },
  {
    id: 'owner',
    header: 'Owner',
    cell: ({ row }) => (
      <span className="whitespace-nowrap text-muted-foreground">
        {row.original.owner}
      </span>
    ),
  },
]

import { Fragment, useMemo } from 'react'
import { FolderOpen } from 'lucide-react'
import {
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type {
  ExpandedState,
  OnChangeFn,
  RowSelectionState,
  SortingState,
} from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { cn } from '#/lib/utils'
import { columns } from './columns'
import type { BrowserMeta } from './columns'
import type { FolderEntry } from './data'
import { FileDetails } from './file-details'
import { sortEntries } from './files'
import type { SortKey } from './files'

// Secondary columns step aside on small screens; the details row has them
const responsive: Record<string, string> = {
  kind: 'hidden md:table-cell',
  owner: 'hidden lg:table-cell',
  modified: 'hidden sm:table-cell',
}

export interface BrowserState {
  sorting: SortingState
  rowSelection: RowSelectionState
  expanded: ExpandedState
}

export function FileTable({
  folder,
  path,
  state,
  onSortingChange,
  onRowSelectionChange,
  onExpandedChange,
  meta,
}: {
  folder: FolderEntry
  /** The folders from the root to `folder`, for the details' location */
  path: FolderEntry[]
  state: BrowserState
  onSortingChange: OnChangeFn<SortingState>
  onRowSelectionChange: OnChangeFn<RowSelectionState>
  onExpandedChange: OnChangeFn<ExpandedState>
  meta: BrowserMeta
}) {
  // Sorted here rather than by TanStack, so folders stay on top either way
  const entries = useMemo(() => {
    const sort = state.sorting.at(0)
    return sortEntries(
      folder.children,
      sort
        ? { id: sort.id as SortKey, desc: sort.desc }
        : { id: 'name', desc: false },
    )
  }, [folder, state.sorting])

  const table = useReactTable({
    data: entries,
    columns,
    getRowId: (entry) => entry.id,
    getRowCanExpand: (row) => row.original.kind === 'file',
    getCoreRowModel: getCoreRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
    manualSorting: true,
    enableMultiSort: false,
    state,
    onSortingChange,
    onRowSelectionChange,
    onExpandedChange,
    meta,
  })

  const rows = table.getRowModel().rows

  return (
    <div className="overflow-hidden rounded-md border">
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((group) => (
            <TableRow key={group.id} className="hover:bg-transparent">
              {group.headers.map((header) => (
                <TableHead
                  key={header.id}
                  aria-sort={
                    header.column.getIsSorted() === 'asc'
                      ? 'ascending'
                      : header.column.getIsSorted() === 'desc'
                        ? 'descending'
                        : undefined
                  }
                  className={cn(
                    responsive[header.column.id],
                    header.column.id === 'select' && 'w-10',
                    header.column.id === 'size' && 'w-28',
                  )}
                >
                  {flexRender(
                    header.column.columnDef.header,
                    header.getContext(),
                  )}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {rows.length ? (
            rows.map((row) => (
              <Fragment key={row.id}>
                <TableRow
                  data-state={row.getIsSelected() ? 'selected' : undefined}
                  className={cn(row.getIsExpanded() && 'border-b-0')}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell
                      key={cell.id}
                      className={cn(
                        responsive[cell.column.id],
                        cell.column.id === 'name' && 'max-w-0 w-full',
                      )}
                    >
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
                {row.getIsExpanded() && row.original.kind === 'file' ? (
                  <TableRow className="bg-muted/30 hover:bg-muted/30">
                    <TableCell />
                    <TableCell colSpan={columns.length - 1}>
                      <FileDetails file={row.original} path={path} />
                    </TableCell>
                  </TableRow>
                ) : null}
              </Fragment>
            ))
          ) : (
            <TableRow className="hover:bg-transparent">
              <TableCell colSpan={columns.length} className="h-40">
                <div className="flex flex-col items-center gap-2 text-center text-sm text-muted-foreground">
                  <FolderOpen aria-hidden className="size-6" />
                  This folder is empty
                </div>
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import { ArrowUp, ChevronRight, Download, Trash2, X } from 'lucide-react'
import type {
  ExpandedState,
  RowSelectionState,
  SortingState,
} from '@tanstack/react-table'

import { Button } from '#/components/ui/button'
import { root as initialRoot } from './data'
import type { FolderEntry } from './data'
import { FileTable } from './data-table'
import { childToward, findPath, formatSize, removeIds, sizeOf } from './files'

export function FileBrowserDemo() {
  const [tree, setTree] = useState<FolderEntry>(initialRoot)
  const [folderId, setFolderId] = useState('all-files/marketing')
  const [sorting, setSorting] = useState<SortingState>([])
  const [rowSelection, setRowSelection] = useState<RowSelectionState>({})
  const [expanded, setExpanded] = useState<ExpandedState>({})
  const [message, setMessage] = useState('')

  const nav = useRef<HTMLElement>(null)
  const frame = useRef<HTMLDivElement>(null)
  // Where focus goes once the new folder has rendered
  const focusNext = useRef<string | null>(null)

  // A deleted folder can't stay open: fall back to the root
  const path = findPath(tree, folderId) ?? [tree]
  const folder = path[path.length - 1]

  useEffect(() => {
    const target = focusNext.current
    if (!target) return
    focusNext.current = null
    const el =
      target === 'crumb'
        ? nav.current?.querySelector<HTMLElement>('[aria-current="page"]')
        : frame.current?.querySelector<HTMLElement>(`[data-entry="${target}"]`)
    el?.focus()
  })

  /**
   * Opening a folder focuses its name in the breadcrumbs. Going back up
   * focuses the folder you came out of, so you keep your place.
   */
  function open(id: string) {
    if (id === folder.id) return
    focusNext.current = folder.id.startsWith(`${id}/`)
      ? childToward(id, folder.id)
      : 'crumb'
    setFolderId(id)
    // Selection and open details belong to the folder you were in
    setRowSelection({})
    setExpanded({})
    setMessage('')
  }

  const selected = folder.children.filter((c) => rowSelection[c.id])
  const selectedSize = selected.reduce((sum, e) => sum + sizeOf(e), 0)
  const parent = path.at(-2)

  function remove() {
    const n = selected.length
    setTree(removeIds(tree, new Set(selected.map((e) => e.id))))
    setRowSelection({})
    setMessage(`Deleted ${n} ${n === 1 ? 'item' : 'items'}.`)
  }

  return (
    <div ref={frame} className="space-y-3">
      <div className="flex min-h-9 flex-wrap items-center gap-2">
        <Button
          variant="outline"
          size="icon"
          className="size-8"
          disabled={!parent}
          aria-label={parent ? `Up to ${parent.name}` : 'Already at the top'}
          onClick={() => parent && open(parent.id)}
        >
          <ArrowUp />
        </Button>
        <nav ref={nav} aria-label="Folder path" className="min-w-0 flex-1">
          <ol className="flex flex-wrap items-center gap-0.5 text-sm">
            {path.map((f, i) => {
              const current = i === path.length - 1
              return (
                <li key={f.id} className="flex min-w-0 items-center gap-0.5">
                  {i > 0 ? (
                    <ChevronRight
                      aria-hidden
                      className="size-3.5 shrink-0 text-muted-foreground"
                    />
                  ) : null}
                  {current ? (
                    <span
                      aria-current="page"
                      tabIndex={-1}
                      className="truncate rounded-sm px-1.5 py-1 font-medium outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
                    >
                      {f.name}
                    </span>
                  ) : (
                    <button
                      type="button"
                      onClick={() => open(f.id)}
                      className="truncate rounded-sm px-1.5 py-1 text-muted-foreground outline-none hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50"
                    >
                      {f.name}
                    </button>
                  )}
                </li>
              )
            })}
          </ol>
        </nav>
      </div>

      <div className="flex min-h-9 flex-wrap items-center justify-between gap-2 rounded-md bg-muted/50 px-3 py-1.5">
        {selected.length ? (
          <>
            <p className="text-sm tabular-nums">
              <span className="font-medium">{selected.length} selected</span>{' '}
              <span className="text-muted-foreground">
                · {formatSize(selectedSize)}
              </span>
            </p>
            <div className="flex items-center gap-1">
              <Button
                variant="ghost"
                size="sm"
                onClick={() =>
                  setMessage(
                    `Preparing ${selected.length} ${selected.length === 1 ? 'item' : 'items'} (${formatSize(selectedSize)}) for download.`,
                  )
                }
              >
                <Download /> Download
              </Button>
              <Button
                variant="ghost"
                size="sm"
                className="text-destructive hover:text-destructive"
                onClick={remove}
              >
                <Trash2 /> Delete
              </Button>
              <Button
                variant="ghost"
                size="icon"
                className="size-8"
                aria-label="Clear selection"
                onClick={() => setRowSelection({})}
              >
                <X />
              </Button>
            </div>
          </>
        ) : (
          <p className="text-sm text-muted-foreground tabular-nums">
            {folder.children.length}{' '}
            {folder.children.length === 1 ? 'item' : 'items'} ·{' '}
            {formatSize(sizeOf(folder))}
          </p>
        )}
        <p
          aria-live="polite"
          className="w-full text-xs text-muted-foreground empty:hidden"
        >
          {message}
        </p>
      </div>

      <FileTable
        folder={folder}
        path={path}
        state={{ sorting, rowSelection, expanded }}
        onSortingChange={setSorting}
        onRowSelectionChange={setRowSelection}
        onExpandedChange={setExpanded}
        meta={{ open }}
      />

      <p className="text-xs text-muted-foreground">
        A folder's name opens it. A file's name shows its details.
      </p>
    </div>
  )
}
